import {Link} from '@github-ui/react-core/link'
import {LawIcon} from '@primer/octicons-react'
import {Button, type ButtonProps} from '@primer/react'
import {clsx} from 'clsx'

import styles from './LicenseSelector.module.css'

export default function LicenseSelector({
  url,
  sx,
  className,
}: {
  url: string
  sx?: ButtonProps['sx']
  className?: string
}) {
  return (
    <Button
      variant="invisible"
      as={Link}
      sx={sx}
      to={url}
      leadingVisual={LawIcon}
      className={clsx(className, styles.Button)}
    >
      Choose a license template
    </Button>
  )
}

try{ LicenseSelector.displayName ||= 'LicenseSelector' } catch {}